IDS = {594: 'sheep', 1060: 'goat', 705: 'cow', 1596: 'cow', 1598: 'cow', 1600: 'cow', 1245: 'pig', 833: 'turkey', 1243: 'goose', 2083: 'chicken', 2085: 'chicken', 2087: 'chicken', 305: 'llama', 1963: 'llama', 1142: 'buffalo', 2590: 'capybara', 65: 'deer', 1796: 'gazelle', 2591: 'guanaco', 1239: 'ibex', 1896: 'argali', 2340: 'mouflon', 1026: 'ostrich', 2597: 'rhea', 2537: 'peacock', 1019: 'zebra', 2098: 'hare', 2099: 'hare', 2100: 'arctic_hare', 2084: 'wild_chicken', 2086: 'wild_chicken', 2088: 'wild_chicken', 48: 'boar', 810: 'boar', 2589: 'boar', 822: 'javelina', 1301: 'elephant', 1139: 'rhino', 1924: 'walrus', 1955: 'red_fox', 1958: 'arctic_fox', 333: 'deer', 936: 'elephant', 285: 'relic'}
NAMES = {'chicken': 'chicken', 'galinha': 'chicken', 'wild chicken': 'wild_chicken', 'galinha selvagem': 'wild_chicken', 'hare': 'hare', 'lebre': 'hare', 'arctic hare': 'arctic_hare', 'lebre artica': 'arctic_hare', 'argali': 'argali', 'mouflon': 'mouflon', 'muflao': 'mouflon', 'rhea': 'rhea', 'ema': 'rhea', 'peacock': 'peacock', 'pavao': 'peacock', 'walrus': 'walrus', 'morsa': 'walrus', 'red fox': 'red_fox', 'raposa vermelha': 'red_fox', 'arctic fox': 'arctic_fox', 'raposa artica': 'arctic_fox'}
SPECIES = {'sheep': ('sheep', 'comida', 'rebanho'), 'goat': ('goat', 'comida', 'rebanho'), 'cow': ('cow', 'comida', 'rebanho'), 'pig': ('pig', 'comida', 'rebanho'), 'turkey': ('turkey', 'comida', 'rebanho'), 'goose': ('goose', 'comida', 'rebanho'), 'chicken': ('chicken', 'comida', 'rebanho'), 'llama': ('llama', 'comida', 'rebanho'), 'buffalo': ('buffalo', 'comida', 'rebanho'), 'capybara': ('capybara', 'comida', 'rebanho'), 'deer': ('deer', 'comida', 'caca'), 'gazelle': ('gazelle', 'comida', 'caca'), 'guanaco': ('guanaco', 'comida', 'caca'), 'ibex': ('ibex', 'comida', 'caca'), 'argali': ('argali', 'comida', 'caca'), 'mouflon': ('mouflon', 'comida', 'caca'), 'ostrich': ('ostrich', 'comida', 'caca'), 'rhea': ('rhea', 'comida', 'caca'), 'peacock': ('peacock', 'comida', 'caca'), 'zebra': ('zebra', 'comida', 'caca'), 'hare': ('hare', 'comida', 'caca'), 'arctic_hare': ('arctic_hare', 'comida', 'caca'), 'wild_chicken': ('wild_chicken', 'comida', 'caca'), 'boar': ('boar', 'comida', 'caca'), 'javelina': ('javelina', 'comida', 'caca'), 'elephant': ('elephant', 'comida', 'caca'), 'rhino': ('rhino', 'comida', 'caca'), 'walrus': ('walrus', 'comida', 'caca'), 'red_fox': ('red_fox', 'ouro', 'caca'), 'arctic_fox': ('arctic_fox', 'ouro', 'caca'), 'relic': ('relic', 'reliquia', 'reliquias')}
