ART_EXTRA = {'walrus': '<ellipse cx="23" cy="29" rx="20" ry="13" fill="#8b7460"/><ellipse cx="31" cy="22" rx="13" ry="12" fill="#ae9580"/><ellipse cx="32" cy="27" rx="10" ry="6" fill="#d0baa0"/><path d="M25 28L25 43L29 38L29 28M35 28L35 43L39 38L39 28" fill="#f0e4c7"/><circle cx="26" cy="18" r="1.8"/><circle cx="37" cy="18" r="1.8"/><ellipse cx="32" cy="24" rx="4" ry="2.5" fill="#36382f"/>'}
HELPERS = "def _gaia_categoria_0414(obj):\n    ident = obj.get('type_id')\n    if ident in _GAIA_COLETAVEIS_0414:\n        return _GAIA_COLETAVEIS_0414[ident]\n    # A known ID must never be reclassified by a misleading reference name.\n    if ident in _GAIA_IDS_044:\n        return None\n    species = _especie_gaia_044(obj)\n    return _GAIA_ESPECIES_0414.get(species)\n\n\ndef _normalizar_recursos_0414(session, points):\n    # Work only on existing model markers: do not recreate manually removed markers.\n    lookup = {}\n    for player in session.header.get('players', ()):\n        if player.get('number') != 0:\n            continue\n        for obj in player.get('objects', ()):\n            lookup[obj.get('instance_id')] = obj.get('object_id')\n    resource_kinds = {'madeira', 'ouro', 'pedra', 'frutas', 'caca', 'rebanho', 'peixes', 'reliquias'}\n    result = []\n    for point in points:\n        if point.get('kind') not in resource_kinds:\n            result.append(point)\n            continue\n        ident = lookup.get(point.get('instance'))\n        if ident is None:\n            ident = point.get('type_id', point.get('id'))\n        if ident is None:\n            # Preserve a marker already classified as a resource by the model,\n            # when no numeric type was supplied.\n            result.append(point)\n            continue\n        category = _GAIA_COLETAVEIS_0414.get(ident)\n        if category is None:\n            continue\n        changed = dict(point)\n        changed['kind'] = category[2]\n        changed['resource'] = category[1]\n        result.append(changed)\n    return result\n\n\ndef _icone_gaia_049(symbol, obj, kind, art_map, ns, images=None):\n    species = kind(obj)\n    raw = _GAIA_ATLAS_0414.get(species)\n    if raw:\n        ET.SubElement(symbol, '{' + ns + '}image', {\n            'x': '-3', 'y': '-3', 'width': '54', 'height': '54',\n            'href': 'data:image/png;base64,' + raw,\n        })\n        return\n    # Preserve existing species drawings and their transparent outlines.\n    _icone_original_0414(symbol, obj, kind, art_map, ns, images)\n"


def adaptar(source):
    tree = ast.parse(source)
    updates = {'_GAIA_IDS_044': IDS, '_GAIA_NAMES_044': NAMES, '_GAIA_ART_044': ART_EXTRA}
    found = set()
    for node in tree.body:
        if not isinstance(node, ast.Assign):continue
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id in updates:
                value = ast.literal_eval(node.value)
                value.update(updates[target.id])
                node.value = ast.parse(repr(value), mode='eval').body
                found.add(target.id)
    if found != set(updates):raise RuntimeError('Catálogo Gaia não reconhecido. Nenhum arquivo foi alterado.')
    new_names = {'_gaia_categoria_0414','_normalizar_recursos_0414'}
    # Save the current vector rendering once; repeat applications reuse it.
    saved = next((n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='_icone_original_0414'),None)
    old = next((n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='_icone_gaia_049'),None)
    if old is None:raise RuntimeError('Este atualizador requer os ícones Gaia da versão 0.4.9 ou posterior.')
    if saved is None:
        old.name='_icone_original_0414'
        # Both 0.4.9 and 0.4.10 renderer signatures are accepted.
        if len(old.args.args)==5:
            old.args.args.append(ast.arg(arg='images'))
            old.args.defaults.append(ast.Constant(value=None))
    else:
        tree.body.remove(old)
    constants = {'_GAIA_COLETAVEIS_0414':CATALOG,'_GAIA_ESPECIES_0414':SPECIES,'_GAIA_ATLAS_0414':ASSETS}
    tree.body[:]=[n for n in tree.body if not (isinstance(n,ast.FunctionDef) and n.name in new_names) and not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id in constants for t in n.targets))]
    for name,value in constants.items():tree.body.append(ast.parse(name+' = '+repr(value)).body[0])
    tree.body.extend(ast.parse(HELPERS).body)
    renders=[n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='render']
    if len(renders)!=1:raise RuntimeError('Renderizador Gaia não reconhecido.')
    render=renders[0]
    loops=[n for n in ast.walk(render) if isinstance(n,ast.For) and ast.unparse(n.iter)=='clusters(neutral)']
    if len(loops)!=1:raise RuntimeError('Agrupamento Gaia não reconhecido.')
    loop=loops[0]
    # Replace the old exclusion rule with the explicit collectible allowlist.
    rules=0
    for n in loop.body:
        if isinstance(n,ast.If) and ast.unparse(n.test) in ('kind(obj) in _GAIA_OCULTAS_045','_gaia_categoria_0414(obj) is None'):
            n.test=ast.parse('_gaia_categoria_0414(obj) is None',mode='eval').body;rules+=1
    if rules!=1:raise RuntimeError('Filtro Gaia não reconhecido.')
    point_updates=0
    for n in ast.walk(render):
        if isinstance(n,ast.Assign) and any(isinstance(t,ast.Subscript) and ast.unparse(t)=="proxy.model['points']" for t in n.targets):
            if not (isinstance(n.value,ast.Call) and isinstance(n.value.func,ast.Name) and n.value.func.id=='_normalizar_recursos_0414'):
                n.value=ast.Call(func=ast.Name(id='_normalizar_recursos_0414',ctx=ast.Load()),args=[ast.Name(id='session',ctx=ast.Load()),n.value],keywords=[])
            point_updates+=1
    if point_updates!=1:raise RuntimeError('Camada de recursos não reconhecida.')
    # Add inspectable resource/category metadata without changing positions or counts.
    for n in ast.walk(loop):
        if isinstance(n,ast.Dict) and any(isinstance(k,ast.Constant) and k.value=='data-gaia' for k in n.keys):
            pairs={k.value:i for i,k in enumerate(n.keys) if isinstance(k,ast.Constant)}
            for key,expression in [('data-resource', '_gaia_categoria_0414(obj)[1]'),('data-collectible', "'capturable' if kind(obj) == 'relic' else 'resource'")]:
                if key in pairs:n.values[pairs[key]]=ast.parse(expression,mode='eval').body
                else:n.keys.append(ast.Constant(value=key));n.values.append(ast.parse(expression,mode='eval').body)
    ast.fix_missing_locations(tree)
    result=ast.unparse(tree)+'\n';compile(result,'gaia_minimapa.py','exec');return result


def main():
    root=Path(__file__).resolve().parent
    path=root/'gaia_minimapa.py'
    if not path.is_file():raise RuntimeError('Extraia o atualizador na pasta GeradorMapaAoE2, junto de gaia_minimapa.py.')
    result=adaptar(path.read_text(encoding='utf-8-sig'))
    backup=root/'backups_atualizacoes'/datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup.mkdir(parents=True);shutil.copy2(path,backup/path.name)
    try:path.write_text(result,encoding='utf-8')
    except Exception:
        shutil.copy2(backup/path.name,path);raise
    print('Lista de Gaia coletáveis aplicada; relíquias preservadas. Backup:',backup)
    print('Execute py -3.12 gerar_atualizacao.py. Use versão 0.4.14 ou superior à última gerada.')


if __name__=='__main__':
    try:main()
    except Exception as error:
        print('ERRO:',error)
        raise SystemExit(1)
